  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Hydrochlorothiazide, the closest analogue sharing the same benzothiadiazine scaffold and differing only by saturation of the thiadiazine ring, has an absolute oral bioavailability of 60.2% in humans after oral dosing versus i.v., strongly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Metolazone, a related sulfonamide diuretic, is available in an approximately 100% bioavailable oral form in humans, supporting high oral bioavailability for this diuretic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Diazoxide, a benzothiadiazine-related drug, is well absorbed orally with 86–96% bioavailability in children and adults, supporting high F for the query's structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the query is chlorothiazide, a benzothiadiazine diuretic. The closest analogue hydrochlorothiazide has absolute oral bioavailability around 60% in humans, well above the 20% threshold, and related thiazide-type diuretics also show high oral bioavailability. The C=N versus C-N ring difference may modestly alter absorption but is not expected to drop F below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for chlorothiazide itself is present in the provided evidence.",
    "The quantitative effect of the unsaturated thiadiazine ring on absorption relative to hydrochlorothiazide is not directly measured.",
    "Low-similarity diuretics with low reported F are methodologically limited and not sufficiently transferable to override the close hydrochlorothiazide analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

